    @SerialName("newpageid")
    val newpageid: Int = 0,

    /** Whether the page processing redirect directly to anoter page. */
    @Serializable(with = MoodleBooleanSerializer::class)
    @SerialName("inmediatejump")
    val inmediatejump: Boolean = false,

    /** Whether there is not a default response. */
    @Serializable(with = MoodleBooleanSerializer::class)
    @SerialName("nodefaultresponse")
    val nodefaultresponse: Boolean = false,

    /** The response feedback. */
    @SerialName("feedback")
    val feedback: String = "",

    /** Number of attempts remaining. */
    @SerialName("attemptsremaining")
    val attemptsremaining: Int = 0,

    /** Whether the answer is correct. */
    @Serializable(with = MoodleBooleanSerializer::class)
    @SerialName("correctanswer")
    val correctanswer: Boolean = false,

    /** Whether there aren't answers. */
    @Serializable(with = MoodleBooleanSerializer::class)
    @SerialName("noanswer")
    val noanswer: Boolean = false,

    /** Whether is a essay question. */
    @Serializable(with = MoodleBooleanSerializer::class)
    @SerialName("isessayquestion")
    val isessayquestion: Boolean = false,

    /** Whether we reachered the max number of attempts. */
    @Serializable(with = MoodleBooleanSerializer::class)
    @SerialName("maxattemptsreached")
    val maxattemptsreached: Boolean = false,

    /** The response. */
    @SerialName("response")
    val response: String = "",

    /** The student answer. */
    @SerialName("studentanswer")
    val studentanswer: String = "",

    /** The user response. */
    @SerialName("userresponse")
    val userresponse: String = "",

    /** Whether the user is reviewing. */
    @Serializable(with = MoodleBooleanSerializer::class)
    @SerialName("reviewmode")
    val reviewmode: Boolean = false,

    /** The ongoing message. */
    @SerialName("ongoingscore")
    val ongoingscore: String = "",

    /** Progress percentage in the lesson. */
    @SerialName("progress")
    val progress: Int = 0,

    /** Whether we should display the menu or not in this page. */
    @Serializable(with = MoodleBooleanSerializer::class)
    @SerialName("displaymenu")
    val displaymenu: Boolean = false,

    @SerialName("messages")
    val messages: List<MoodleLessonFinishAttemptResponseMessage> = emptyList(),

    /** list of warnings */
    @SerialName("warnings")
    val warnings: List<MoodleWarning> = emptyList()
)
